from fastapi import Depends, Header, HTTPException
from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession

from .db import get_db
from .models import Membership, User, Workspace
from .security import decode_token


async def current_user(
    authorization: str = Header(default=""), db: AsyncSession = Depends(get_db)
) -> User:
    if not authorization.startswith("Bearer "):
        raise HTTPException(401, "Not authenticated")
    user_id = decode_token(authorization.removeprefix("Bearer ").strip())
    if not user_id:
        raise HTTPException(401, "Invalid or expired token")
    user = await db.get(User, user_id)
    if not user:
        raise HTTPException(401, "User not found")
    return user


async def workspace_for(
    workspace_id: str, user: User, db: AsyncSession, min_role: str = "member"
) -> Workspace:
    m = (
        await db.execute(
            select(Membership).where(
                Membership.user_id == user.id, Membership.workspace_id == workspace_id
            )
        )
    ).scalar_one_or_none()
    if not m:
        raise HTTPException(403, "No access to this workspace")
    if min_role in ("owner", "admin") and m.role == "member":
        raise HTTPException(403, "Insufficient role")
    ws = await db.get(Workspace, workspace_id)
    if not ws:
        raise HTTPException(404, "Workspace not found")
    return ws

