"""CPU transcription with faster-whisper (int8), word-level timestamps."""

import asyncio

from app.config import get_settings

_model = None


def _get_model():
    global _model
    if _model is None:
        from faster_whisper import WhisperModel

        _model = WhisperModel(get_settings().whisper_model, device="cpu", compute_type="int8")
    return _model


def _transcribe_sync(audio_path: str) -> dict:
    model = _get_model()
    segments, info = model.transcribe(audio_path, word_timestamps=True, vad_filter=True)
    out = []
    for seg in segments:
        out.append(
            {
                "start": round(seg.start, 2),
                "end": round(seg.end, 2),
                "text": seg.text.strip(),
                "words": [
                    {"w": w.word.strip(), "s": round(w.start, 2), "e": round(w.end, 2)}
                    for w in (seg.words or [])
                ],
            }
        )
    return {"language": info.language, "segments": out}


async def transcribe(audio_path: str) -> dict:
    return await asyncio.to_thread(_transcribe_sync, audio_path)

