  title: "ClipForge — AI Faceless Content Studio",
  description:
    "Turn long-form video into viral short-form clips automatically. Ingest, transcribe, find the best moments, caption, render, publish.",
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

