"use client";

import { useState } from "react";
import { api } from "@/lib/api";

export default function Landing() {
  const [mode, setMode] = useState<"login" | "register">("register");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setErr("");
    setBusy(true);
    try {
      const data = await api<{ token: string }>(`/auth/${mode}`, {
        method: "POST",
        body: mode === "register" ? { email, password, name } : { email, password },
      });
      localStorage.setItem("cf_token", data.token);
      const me = await api<{ workspaces: { id: string }[] }>("/auth/me");
      localStorage.setItem("cf_ws", me.workspaces[0]?.id || "");
      window.location.href = "/dashboard";
    } catch (e: any) {
      setErr(e.message);
    } finally {
      setBusy(false);
    }
  }

  return (
    <main className="min-h-screen flex flex-col">
      <nav className="flex items-center justify-between px-8 py-6 max-w-6xl mx-auto w-full">
        <div className="text-lg font-bold tracking-tight">
          Clip<span className="text-brand">Forge</span>
        </div>
        <span className="text-xs text-zinc-500">content.revsports.ca</span>
      </nav>

      <div className="flex-1 grid lg:grid-cols-2 gap-16 items-center max-w-6xl mx-auto px-8 py-12 w-full">
        <div>
          <div className="chip border-brand/40 text-brand mb-6">AI content engine · self-hosted</div>
          <h1 className="text-5xl font-extrabold leading-[1.05] tracking-tight">
            Turn any podcast into{" "}
            <span className="bg-gradient-to-r from-brand via-indigo-400 to-brand-2 bg-clip-text text-transparent">
              viral clips
            </span>{" "}
            on autopilot.
          </h1>
          <p className="mt-6 text-zinc-400 text-lg leading-relaxed">
            Paste a YouTube URL. ClipForge transcribes the whole thing, finds the most
            entertaining, controversial and important moments, reframes to 9:16, burns
            animated captions, and hands you finished clips ready for TikTok, Shorts and Reels.
          </p>
          <ul className="mt-8 space-y-2 text-sm text-zinc-400">
            <li>⚡ Whisper transcription with word-level timing</li>
            <li>🧠 AI moment detection — bring your own key, or free heuristic mode</li>
            <li>🎬 Hormozi-style animated captions, queue-based rendering</li>
          </ul>
        </div>

        <form onSubmit={submit} className="glass p-8 w-full max-w-md justify-self-center">
          <div className="flex gap-1 mb-6 p-1 rounded-xl bg-white/5">
            {(["register", "login"] as const).map((m) => (
              <button
                key={m}
                type="button"
                onClick={() => setMode(m)}
                className={`flex-1 rounded-lg py-2 text-sm font-medium transition ${
                  mode === m ? "bg-brand text-white" : "text-zinc-400 hover:text-white"
                }`}
              >
                {m === "register" ? "Create account" : "Sign in"}
              </button>
            ))}
          </div>
          {mode === "register" && (
            <input className="input mb-3" placeholder="Your name" value={name} onChange={(e) => setName(e.target.value)} />
          )}
          <input className="input mb-3" type="email" required placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} />
          <input className="input mb-4" type="password" required minLength={8} placeholder="Password (8+ chars)" value={password} onChange={(e) => setPassword(e.target.value)} />
          {err && <p className="text-rose-400 text-sm mb-3">{err}</p>}
          <button className="btn-primary w-full" disabled={busy}>
            {busy ? "One sec…" : mode === "register" ? "Start creating free" : "Sign in"}
          </button>
          <p className="mt-4 text-[11px] text-zinc-500 text-center">
            100 free credits on signup · no card required
          </p>
        </form>
      </div>
    </main>
  );
}

