"use client";

import { useState } from "react";
import Shell from "@/components/Shell";
import { api, wsId } from "@/lib/api";

const styles = [
  { id: "hormozi", name: "Hormozi", desc: "Bold uppercase, gold highlight" },
  { id: "tiktok", name: "TikTok", desc: "Punchy pink word pop" },
  { id: "minimal", name: "Minimal", desc: "Clean, subtle captions" },
];

export default function ClipStudio() {
  const [url, setUrl] = useState("");
  const [maxClips, setMaxClips] = useState(8);
  const [style, setStyle] = useState("hormozi");
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setErr("");
    setBusy(true);
    try {
      const p = await api(`/workspaces/${wsId()}/projects/clip-youtube`, {
        method: "POST",
        body: { source_url: url, options: { max_clips: maxClips, caption_style: style } },
      });
      window.location.href = `/projects/${p.id}`;
    } catch (e: any) {
      setErr(e.message);
      setBusy(false);
    }
  }

  return (
    <Shell>
      <h1 className="text-2xl font-bold tracking-tight mb-2">Clip Studio</h1>
      <p className="text-zinc-400 mb-8 text-sm">
        Paste a long-form video — a podcast, interview or stream. We&apos;ll pull out the most
        entertaining, controversial and important moments as ready-to-post vertical clips.
      </p>

      <form onSubmit={submit} className="glass p-8 max-w-2xl space-y-6">
        <div>
          <label className="text-sm font-medium mb-2 block">Source URL</label>
          <input
            className="input"
            required
            placeholder="https://www.youtube.com/watch?v=…"
            value={url}
            onChange={(e) => setUrl(e.target.value)}
          />
          <p className="text-[11px] text-zinc-500 mt-2">
            Use content you own or have rights to clip.
          </p>
        </div>

        <div>
          <label className="text-sm font-medium mb-2 block">
            Max clips: <span className="text-brand-2">{maxClips}</span>
          </label>
          <input type="range" min={3} max={15} value={maxClips} onChange={(e) => setMaxClips(+e.target.value)} className="w-full accent-violet-500" />
        </div>

        <div>
          <label className="text-sm font-medium mb-2 block">Caption style</label>
          <div className="grid grid-cols-3 gap-3">
            {styles.map((s) => (
              <button
                key={s.id}
                type="button"
                onClick={() => setStyle(s.id)}
                className={`rounded-xl border p-4 text-left transition ${
                  style === s.id ? "border-brand bg-brand/10" : "border-line hover:bg-white/5"
                }`}
              >
                <div className="font-semibold text-sm">{s.name}</div>
                <div className="text-[11px] text-zinc-500 mt-1">{s.desc}</div>
              </button>
            ))}
          </div>
        </div>

        {err && <p className="text-rose-400 text-sm">{err}</p>}
        <button className="btn-primary w-full text-base py-3" disabled={busy}>
          {busy ? "Queueing…" : "⚡ Generate clips (10 credits)"}
        </button>
      </form>
    </Shell>
  );
}

