      <p className="text-xs text-zinc-500 mb-8 truncate">{p.source_url}</p>

      {running && (
        <div className="glass p-6 mb-8">
          <div className="flex justify-between text-sm mb-3">
            <span className="font-medium">{p.stage}</span>
            <span className="text-brand-2">{p.progress}%</span>
          </div>
          <div className="h-2 rounded-full bg-white/10 overflow-hidden mb-5">
            <div className="h-full bg-gradient-to-r from-brand to-brand-2 transition-all duration-700" style={{ width: `${p.progress}%` }} />
          </div>
          <div className="flex gap-2">
            {stages.map((s, i) => (
              <div key={s} className={`chip ${i < stageIdx ? "border-emerald-500/40 text-emerald-400" : i === stageIdx ? "border-brand/50 text-brand animate-pulse" : "border-line text-zinc-600"}`}>
                {s}
              </div>
            ))}
          </div>
        </div>
      )}

      {p.status === "failed" && (
        <div className="glass p-6 mb-8 border-rose-500/30">
          <p className="text-rose-400 font-medium mb-2">Project failed</p>
          <p className="text-xs text-zinc-500 mb-4 font-mono">{p.error}</p>
          <button className="btn-ghost" onClick={async () => {
            await api(`/workspaces/${wsId()}/projects/${p.id}/retry`, { method: "POST" });
            window.location.reload();
          }}>Retry</button>
        </div>
      )}

      {p.clips?.length > 0 && (
        <>
          <h2 className="text-sm font-semibold text-zinc-400 uppercase tracking-wider mb-4">
            Clips ({p.clips.length})
          </h2>
          <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-5">
            {p.clips.map((c: any) => (
              <div key={c.id} className="glass overflow-hidden flex flex-col">
                {c.status === "done" && c.video_url ? (
                  <video controls poster={c.thumb_url || undefined} src={c.video_url} className="aspect-[9/16] max-h-80 w-full object-cover bg-black" preload="none" />
                ) : (
                  <div className="aspect-[9/16] max-h-80 w-full bg-white/5 flex items-center justify-center text-zinc-500 text-sm">
                    {c.status === "failed" ? "Render failed" : "Rendering…"}
                  </div>
                )}
                <div className="p-4 flex-1 flex flex-col gap-2">
                  <div className="flex items-center gap-2">
                    <span className={`chip ${catColor[c.category] || "border-line text-zinc-400"}`}>{c.category}</span>
                    <span className="chip border-brand/40 text-brand">🔥 {Math.round(c.score)}</span>
                    <span className="text-[11px] text-zinc-500 ml-auto">{c.duration}s</span>
                  </div>
                  <div className="font-semibold text-sm leading-snug">{c.title}</div>
                  <div className="text-[11px] text-zinc-500 leading-relaxed">{c.reason}</div>
                  {c.video_url && (
                    <a href={c.video_url} download className="btn-ghost mt-auto text-xs">⬇ Download MP4</a>
                  )}
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </Shell>
  );
}

